export const mkVoiceBroadcastInfoStateEvent = (
    roomId: string,
    state: VoiceBroadcastInfoState,
    senderId: string,
    senderDeviceId: string,
    startedInfoEvent?: MatrixEvent,
): MatrixEvent => {
    const relationContent = {};

    if (startedInfoEvent) {
